# GENERATED by scripts/sync_hems_core.py from hems/core/hems/battery.py; do not edit here.
"""Battery planner: dynamic programming over quarter-hour slots (rolling horizon).

Why DP and not LP: one storage state, small horizon (<= 96 slots) -> exact, pure
Python, no solver dependency, easy to trace. Sell hours are chosen over the whole
horizon *cycle* (charge -> discharge), so "best N hours after charging" falls out
of the optimisation instead of a calendar-day heuristic.
"""
from dataclasses import dataclass, field

from .slots import SLOT_H

INF = float("inf")
REASON_DIGITS = 3                # the reason text prints prices with this many decimals; its comparison is judged on what it prints


@dataclass
class BatteryConfig:
    capacity_kwh: float = 25.0
    max_power_kw: float = 8.0
    hard_min_soc: float = 0.05       # absolute battery minimum (fraction); never discharged below
    reserve_soc: float = 0.30        # sell floor: export stops here; below it the battery only covers the house, down to hard_min_soc
    reserve_max_soc: float = 0.30    # upper bound of the usage-based sell floor (hems.reserve); equal to reserve_soc = a fixed floor
    reserve_load_factor: float = 1.3  # safety factor on the load forecast when sizing the usage-based floor (about its P90)
    max_soc: float = 1.00
    round_trip_eff: float = 0.82     # measured 3-12 Oct 2026 (docs/hems/intake-decisions.md); a setting
    min_profit_margin: float = 0.10  # EUR per kWh discharged: a cycle must earn at least this, net of round-trip losses
    hold_cost_kwh_h: float = 0.002   # EUR per kWh stored per hour: a waiting premium, so equal prices charge late instead of early (replay 4-11 Oct)
    step_kwh: float = 0.25           # SoC grid resolution
    allow_grid_charge: bool = True
    future_peak_haircut: float = 0.0  # EUR per kWh taken off the typical recent peak when valuing energy kept past the horizon (hems.terminal); a setting

    def __post_init__(self) -> None:
        """Fail fast on an inconsistent floor: the reserve cannot sit below the hard minimum."""
        if not 0.0 <= self.hard_min_soc <= self.reserve_soc <= self.max_soc <= 1.0:
            raise ValueError("need 0 <= hard_min_soc <= reserve_soc <= max_soc <= 1")
        if not self.reserve_soc <= self.reserve_max_soc <= self.max_soc:
            raise ValueError("need reserve_soc <= reserve_max_soc <= max_soc")


@dataclass
class Slot:
    import_price: float
    export_price: float
    load_kwh: float = 0.0            # house consumption in the slot
    pv_kwh: float = 0.0              # PV production in the slot
    reserve_soc: float | None = None  # reserve floor for this slot (fraction); None = BatteryConfig.reserve_soc
    import_cap_kwh: float | None = None  # most grid energy the connection may deliver in the slot; charging never takes the import above it (None = no cap)


@dataclass
class PlanSlot:
    index: int
    action: str                      # charge | discharge | idle
    battery_kwh: float               # AC side, + charge / - discharge
    soc_kwh: float                   # at end of slot
    grid_kwh: float                  # + import / - export
    cost: float
    reason: str = ""
    stored_value: float | None = None  # EUR per kWh kept in the battery after this slot (marginal value from the DP)
    reason_code: str = ""            # sell | buy | hold | floor | full | none
    sell_value: float | None = None  # EUR per stored kWh when selling (or avoiding import) in this slot, net of margin and loss
    buy_cost: float | None = None    # EUR per stored kWh when charging in this slot, net of loss
    at_floor: bool = False           # SoC at the end of the slot sits on the floor
    at_full: bool = False            # SoC at the end of the slot sits at the maximum
    own_kwh: float = 0.0             # AC flow of plain self-consumption in this slot; a charge or sale is what the plan adds to it

    @property
    def sold_kwh(self) -> float:
        """AC energy discharged beyond self-consumption: the sale (0 outside a sale)."""
        return max(0.0, self.own_kwh - self.battery_kwh)

    @property
    def bought_kwh(self) -> float:
        """AC energy charged beyond self-consumption: the grid charge (0 outside a charge window)."""
        return max(0.0, self.battery_kwh - self.own_kwh)


@dataclass
class Plan:
    slots: list[PlanSlot] = field(default_factory=list)
    total_cost: float = 0.0          # cash grid cost of the horizon
    baseline_cost: float = 0.0       # same horizon without battery

    @property
    def saving(self) -> float:
        """Cost avoided versus the same horizon without a battery (EUR)."""
        return self.baseline_cost - self.total_cost


def _ac(d: int, step: float, eff: float) -> float:
    """AC-side energy of a SoC change of `d` steps: charging loses energy before the cells, discharging after."""
    return d * step / eff if d > 0 else d * step * eff


def _grid_cost(net_kwh: float, s: Slot) -> float:
    """Cost of a grid exchange in the slot: import at the import price, export at the export price."""
    return net_kwh * s.import_price if net_kwh > 0 else net_kwh * s.export_price


def _stored_value(next_values: list[float], k: int, hi: int, step: float) -> float | None:
    """Marginal value (EUR per stored kWh) of one more step of SoC, from the next slot's cost-to-go table."""
    low, high = (k, k + 1) if k < hi else (k - 1, k)
    if low < 0 or INF in (abs(next_values[low]), abs(next_values[high])):
        return None
    return -(next_values[high] - next_values[low]) / step


@dataclass(frozen=True)
class Reasoning:
    """The comparison behind one slot's action, in EUR per kWh stored."""
    code: str                        # sell | buy | hold | floor | full | none
    text: str
    sell: float | None = None
    buy: float | None = None


def _says(left: str, strict: str, right: str, larger: float, smaller: float) -> str | None:
    """'left > right' (or '<') when the printed numbers say so, 'left >= right' (or '<=') when they print equal, else None.

    The comparison is judged on the rounded numbers the text shows: a reader checks the text against what is on screen,
    so 'buy 0.330 < keep 0.328' is false even when the unrounded values differ by 0.0004. `larger` and `smaller` are the
    printed numbers of the side that must be the larger and the smaller one."""
    if larger > smaller:
        return f"{left} {strict} {right}"
    if larger == smaller:
        return f"{left} {strict}= {right}"
    return None


def _reason(action: str, s: Slot, grid_kwh: float, stored_value: float | None, eff: float, cfg: BatteryConfig,
            at_floor: bool, at_full: bool) -> Reasoning:
    """Why the planner chose `action`: selling net of the minimum profit margin, buying net of loss, or keeping.

    The 'keep' value is what the rest of the horizon would pay for that kWh; every decision is that comparison."""
    if stored_value is None:
        return Reasoning("none", action)
    net = s.load_kwh - s.pv_kwh
    # The marginal kWh sold is priced where it lands: a discharge that exceeds the house load is exported, so it earns the
    # export price even while the house is a net consumer (the planner's own cost uses the grid flow after the discharge).
    lands_on_import = grid_kwh > 0 if action == "discharge" else net > 0
    sell = eff * ((s.import_price if lands_on_import else s.export_price) - cfg.min_profit_margin)
    buy_price = s.import_price if (grid_kwh > 0 if action == "charge" else net >= 0) else s.export_price
    buy = buy_price / eff
    # The marginal comparison explains most choices. The value function is not convex (the margin only applies to
    # discharging), so now and then the plan sells below or buys above the end-of-slot 'keep' because the whole path
    # pays; then the text says so instead of printing a comparison that is false on its face.
    if action == "discharge":
        shown_sell, shown_keep = round(sell, REASON_DIGITS), round(stored_value, REASON_DIGITS)
        text = _says(f"sell {shown_sell:.3f}", ">", f"keep {shown_keep:.3f}", shown_sell, shown_keep) or \
            f"plan-level sale: sell {shown_sell:.3f} < keep {shown_keep:.3f} at the margin"
        return Reasoning("sell", text, sell, buy)
    if action == "charge":
        shown_buy, shown_keep = round(buy, REASON_DIGITS), round(stored_value, REASON_DIGITS)
        text = _says(f"buy {shown_buy:.3f}", "<", f"keep {shown_keep:.3f}", shown_keep, shown_buy) or \
            f"plan-level charge: buy {shown_buy:.3f} > keep {shown_keep:.3f} at the margin"
        return Reasoning("buy", text, sell, buy)
    shown_sell, shown_buy, shown_keep = (round(v, REASON_DIGITS) for v in (sell, buy, stored_value))
    if at_floor and sell > stored_value:
        return Reasoning("floor", f"hold at reserve floor ({_says(f'sell {shown_sell:.3f}', '>', f'keep {shown_keep:.3f}', shown_sell, shown_keep)})", sell, buy)
    if at_full and buy < stored_value:
        return Reasoning("full", f"hold, battery full ({_says(f'buy {shown_buy:.3f}', '<', f'keep {shown_keep:.3f}', shown_keep, shown_buy)})", sell, buy)
    return Reasoning("hold", f"hold: sell {sell:.3f} <= keep {stored_value:.3f} <= buy {buy:.3f}", sell, buy)


def floor_fraction(slot: Slot | None, cfg: BatteryConfig) -> float:
    """SoC floor of a slot as a fraction: its reserve (or the config default), never below the hard minimum.

    The executor uses the same floor as the planner, so a plan and its safety check cannot disagree."""
    reserve = cfg.reserve_soc if slot is None or slot.reserve_soc is None else slot.reserve_soc
    return max(cfg.hard_min_soc, reserve)


def _floor_levels(slots: list[Slot], cfg: BatteryConfig) -> list[int]:
    """Sell floor per slot in grid steps."""
    return [round(floor_fraction(s, cfg) * cfg.capacity_kwh / cfg.step_kwh) for s in slots]


@dataclass(frozen=True)
class _Steps:
    """Grid-step limits of one planning run: hard minimum, maximum, and the most charge or discharge steps per slot."""
    lo: int
    hi: int
    max_charge: int
    max_discharge: int


def self_consumption_step(net_kwh: float, k: int, eff: float, step: float, limits: _Steps) -> int:
    """SoC steps of plain self-consumption in one slot: cover the house (net > 0) down to the hard minimum, or store the PV
    surplus (net < 0) up to the maximum, within the inverter limit.

    This is what the battery does outside a charge or sell window (the own grid-follow keeps the meter at 0 W). The step is
    rounded to the nearest grid step: rounding down would leave a house load under one step per quarter (1 kW at 0.25 kWh)
    uncovered all evening; the rest of a step shows as a small import or export in the plan, the grid-follow takes it out live."""
    if net_kwh > 0:
        return -min(round(net_kwh / eff / step), k - min(limits.lo, k), limits.max_discharge)
    return min(round(-net_kwh * eff / step), limits.hi - k, limits.max_charge)


def plan(slots: list[Slot], soc_kwh: float, cfg: BatteryConfig,
         terminal_value: float | None = None) -> Plan:
    """Optimal battery schedule. terminal_value: EUR/kWh credit for energy left at
    the end of the horizon (default: cheapest import price in horizon * eff, i.e.
    what it would cost to refill). The floor may differ per slot (Slot.reserve_soc);
    The floor is a sell floor: below it the battery still covers the house (self-consumption) down to hard_min_soc, it only
    stops exporting. Every slot is self-consumption unless the plan charges more (a charge window) or discharges more (a sale);
    there is no 'hold' while the house imports, the battery always keeps the meter at 0 W outside a window."""
    n = len(slots)
    eff = cfg.round_trip_eff ** 0.5
    step = cfg.step_kwh
    floors = _floor_levels(slots, cfg)
    hi = round(cfg.max_soc * cfg.capacity_kwh / step)
    hard_lo = round(cfg.hard_min_soc * cfg.capacity_kwh / step)
    start = min(max(round(soc_kwh / step), 0), hi)
    # The inverter limit is on the AC side: charging loses energy before it reaches the cells, discharging after.
    hold = cfg.hold_cost_kwh_h * SLOT_H * step    # per grid step of SoC held through one slot
    max_charge = int(cfg.max_power_kw * SLOT_H * eff / step)
    max_discharge = int(cfg.max_power_kw * SLOT_H / eff / step)
    limits = _Steps(hard_lo, hi, max_charge, max_discharge)
    if terminal_value is None:
        terminal_value = min(s.import_price for s in slots) * eff if slots else 0.0

    # value[t][k]: minimal cost-to-go from slot t at SoC level k
    value = [[INF] * (hi + 1) for _ in range(n + 1)]
    for k in range(hi + 1):
        value[n][k] = -terminal_value * k * step
    choice = [[0] * (hi + 1) for _ in range(n)]

    for t in range(n - 1, -1, -1):
        s = slots[t]
        net = s.load_kwh - s.pv_kwh
        lo = floors[t]
        for k in range(hi + 1):
            best, best_d = INF, 0
            own = self_consumption_step(net, k, eff, step, limits)
            own_ac = _ac(own, step, eff)
            for d in range(-max_discharge, max_charge + 1):      # d>0 charge steps (SoC side)
                k2 = k + d
                if k2 > hi:
                    continue
                if d < own and k2 < min(lo, k):              # discharging past self-consumption is a sale: never below the sell floor
                    continue
                dsoc = d * step
                ac = _ac(d, step, eff)                       # AC-side energy
                if d > 0 and not cfg.allow_grid_charge and net + ac > 0 and net >= 0:
                    # only allow charging from surplus PV
                    if ac > max(0.0, -net) + 1e-9:
                        continue
                if d > 0 and s.import_cap_kwh is not None and net + ac > s.import_cap_kwh + 1e-9:
                    continue                                  # a physical limit of the connection (3x25 A), not a price: holding or discharging stays possible
                # the margin is on what a sale adds beyond self-consumption: covering the house needs no margin
                c = _grid_cost(net + ac, s) + (cfg.min_profit_margin * (own_ac - ac) if d < own else 0.0) + hold * k2
                c += value[t + 1][k2]
                if c < best:
                    best, best_d = c, d
            value[t][k] = best
            choice[t][k] = best_d

    out = Plan()
    k = start
    for t in range(n):
        s = slots[t]
        net = s.load_kwh - s.pv_kwh
        own = self_consumption_step(net, k, eff, step, limits)
        d = choice[t][k] if value[t][k] < INF else own
        ac = _ac(d, step, eff)
        grid = net + ac
        k += d
        action = "charge" if d > own else "discharge" if d < own else "idle"
        keep = _stored_value(value[t + 1], k, hi, step)
        at_floor, at_full = k <= floors[t], k >= hi
        why = _reason(action, s, grid, keep, eff, cfg, at_floor=at_floor, at_full=at_full)
        out.slots.append(PlanSlot(t, action, ac, k * step, grid, _grid_cost(grid, s), why.text, keep, why.code, why.sell, why.buy, at_floor, at_full,
                                  _ac(own, step, eff)))
        out.total_cost += _grid_cost(grid, s)    # cash only: the margin shapes decisions, it is not money
        out.baseline_cost += _grid_cost(net, s)
    return out
